/* A username and a store's address change only through Storelib's server (round AX, database security). profiles.username is storelib.com/{name} and creators.slug is {name}.storelib.com, the store's website. Every rule on a name lives in the app: the format, the reserved words, a name for a fake sign in page or support desk (lib/security/phishing-names: paypal-login, apple-support), a name somebody gave up that still redirects (username_history), another store's or website's address (lib/profile/ensure-username handleAvailable). The owner policies on profiles and creators check only whose row it is, so with the public key a signed in account could write its own username or store address straight through the public API, past all of them: creators.slug = 'paypal-login' made paypal-login.storelib.com, a phishing address on Storelib's own domain with the store's website on it. /app Settings and the seller onboarding now move a handle through PATCH /api/profile/username (lib/profile/move-handle.ts), which runs those checks with the server key. Now a write with the browser key (anon or authenticated) that sets or changes profiles.username, or sets or changes creators.slug to anything but the account's own username, is refused with insufficient_privilege (42501) and the message "Change your username in Settings". A save that leaves either one as it is, in any case, passes, so every other field of a profile or a store saves exactly as before; a new store row that carries the account's own username (the seller onboarding writes it after the server gave it) passes; the server (service role), database functions and the sign up trigger are not checked here. The helper public.storelib_own_username(uuid) runs with its owner's rights and returns only an account's username, which public profiles already show. It does NOT change any row, and names taken before these rules keep working. LOCKS: CREATE TRIGGER takes a short lock on profiles and creators, held until the paste ends. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_own_username(p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT p.username FROM public.profiles p WHERE p.id = p_user $f$;
REVOKE ALL ON FUNCTION public.storelib_own_username(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_own_username(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.profiles_username_server_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; IF TG_OP = 'INSERT' AND NEW.username IS NULL THEN RETURN NEW; END IF; IF TG_OP = 'UPDATE' AND lower(coalesce(NEW.username, '')) = lower(coalesce(OLD.username, '')) THEN RETURN NEW; END IF; RAISE EXCEPTION 'Change your username in Settings' USING ERRCODE = '42501', DETAIL = 'profiles.username is written by the server only (part 462).'; END $f$;
REVOKE ALL ON FUNCTION public.profiles_username_server_only() FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.creators_slug_server_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; IF TG_OP = 'UPDATE' AND lower(coalesce(NEW.slug, '')) = lower(coalesce(OLD.slug, '')) THEN RETURN NEW; END IF; IF NEW.slug IS NOT NULL AND btrim(NEW.slug) <> '' AND lower(NEW.slug) = lower(coalesce(public.storelib_own_username(CASE WHEN TG_OP = 'UPDATE' THEN OLD.user_id ELSE NEW.user_id END), '')) THEN RETURN NEW; END IF; RAISE EXCEPTION 'Change your username in Settings' USING ERRCODE = '42501', DETAIL = 'creators.slug is written by the server only, or as the account''s own username (part 462).'; END $f$;
REVOKE ALL ON FUNCTION public.creators_slug_server_only() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.profiles') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'username') THEN RAISE NOTICE 'part 462: public.profiles or profiles.username does not exist here, skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS profiles_username_server_only ON public.profiles; CREATE TRIGGER profiles_username_server_only BEFORE INSERT OR UPDATE OF username ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profiles_username_server_only(); IF to_regclass('public.creators') IS NULL OR (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'creators' AND column_name IN ('slug', 'user_id')) < 2 THEN RAISE NOTICE 'part 462: public.creators, creators.slug or creators.user_id does not exist here, store addresses skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS creators_slug_server_only ON public.creators; CREATE TRIGGER creators_slug_server_only BEFORE INSERT OR UPDATE OF slug ON public.creators FOR EACH ROW EXECUTE FUNCTION public.creators_slug_server_only(); END $do$;
notify pgrst, 'reload schema';
